"""
wizard_window.py — top-level Adw.ApplicationWindow containing the NavigationView.
Each screen is an Adw.NavigationPage pushed/popped as the user progresses.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, GLib

from .state import WizardState
from .screens.s0_welcome import WelcomeScreen
from .screens.s1_detection import DetectionScreen
from .screens.s2_nics import NICScreen
from .screens.s3_gpu import GPUScreen
from .screens.s4_appvms import AppVMScreen
from .screens.s5_review import ReviewScreen
from .screens.s6_apply import ApplyScreen


class WizardWindow(Adw.ApplicationWindow):
    def __init__(self, **kwargs):
        super().__init__(**kwargs)

        self.set_title("BulwarkOS Setup")
        self.set_default_size(680, 560)
        self.set_resizable(False)

        # Shared state — passed by reference to every screen
        self.state = WizardState()

        # Navigation stack
        self.nav = Adw.NavigationView()
        self.set_content(self.nav)

        # Build all screens upfront (lightweight — they don't do I/O in __init__)
        self._screens = {
            "welcome":   WelcomeScreen(self.state, self._go_to),
            "detect":    DetectionScreen(self.state, self._go_to),
            "nics":      NICScreen(self.state, self._go_to),
            "gpu":       GPUScreen(self.state, self._go_to),
            "appvms":    AppVMScreen(self.state, self._go_to),
            "review":    ReviewScreen(self.state, self._go_to),
            "apply":     ApplyScreen(self.state, self._go_to),
        }

        # Push the first screen
        self.nav.push(self._screens["welcome"])

    def _go_to(self, screen_id: str):
        """
        Navigate to a named screen.
        'back' pops the current page.
        Any other id pushes the corresponding page.
        """
        if screen_id == "back":
            self.nav.pop()
            return

        page = self._screens.get(screen_id)
        if page is None:
            print(f"[WizardWindow] Unknown screen: {screen_id!r}")
            return

        # Let the screen refresh itself before it's shown
        if hasattr(page, "on_enter"):
            page.on_enter()

        self.nav.push(page)
